{
  "name": "@stalfh/opencode-hud",
  "version": "0.2.2",
  "description": "OpenCode TUI HUD plugin with visual context, usage, cache, spend, and model-flow dashboards.",
  "type": "module",
  "main": "./src/index.ts",
  "types": "./src/index.ts",
  "bin": {
    "opencode-hud": "bin/opencode-hud.js"
  },
  "exports": {
    ".": {
      "types": "./src/index.ts",
      "default": "./src/index.ts"
    },
    "./server": {
      "types": "./src/server.ts",
      "default": "./src/server.ts"
    },
    "./tui": {
      "types": "./src/tui.tsx",
      "default": "./src/tui.tsx"
    }
  },
  "oc-plugin": [
    "server",
    "tui"
  ],
  "files": [
    "bin",
    "src",
    "config",
    "skills",
    "commands",
    "README.md"
  ],
  "scripts": {
    "postinstall": "bun ./src/postinstall.ts",
    "test": "bun test tests/core.test.ts tests/cli.test.ts tests/config-core.test.ts tests/server.test.ts",
    "check": "bun test tests/config/schema.test.ts tests/config/manifest.test.ts tests/config/migrate.test.ts tests/config-core.test.ts tests/metrics/session.test.ts tests/metrics/history.test.ts tests/metrics/models.test.ts tests/data/opencode-config.test.ts tests/data/history-store.test.ts tests/scheduler/hud-resource.test.ts tests/render/sections.test.ts tests/render/bottom.test.ts tests/render/sidebar.test.ts tests/core.test.ts tests/cli.test.ts tests/server.test.ts && bun test --preload @opentui/solid/preload tests/tui.test.ts && bunx tsc --noEmit"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui",
    "hud",
    "tokens",
    "usage"
  ],
  "dependencies": {
    "@opencode-ai/plugin": "^1.15.10",
    "@opentui/solid": "^0.2.7",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "bun-types": "latest"
  }
}
